// tg: code/modules/power/terminal.dm:49
public partial class obj_machinery_power_terminal : obj_machinery_power
{
    // tg: code/modules/power/terminal.dm:49
    public virtual async DmTask dismantle(mob_living user = null, obj_item I = null)
    {
        if (isturf(loc))
        {
            turf T = loc as turf;
            if (T.underfloor_accessibility < UNDERFLOOR_INTERACTABLE)
            {
                balloon_alert(user, I18n.T("must expose the cable terminal!"));
                return;
            }
        }

        if (Dm.truthy(master) && !Dm.truthy(master.can_terminal_dismantle()))
            return;

        user.visible_message(span_notice(I18n.T("[] dismantles the cable terminal from [].", user.name, master)));
        balloon_alert(user, I18n.T("cutting the cables..."));

        playsound(this.loc, Dm.resource("sound/items/deconstruct.ogg"), 50, TRUE);
        if (Dm.truthy(await I.use_tool(this, user, 50)))
        {
            if (Dm.truthy(master) && !Dm.truthy(master.can_terminal_dismantle()))
                return;

            if (prob(50) && Dm.truthy(await electrocute_mob(user as mob_living_carbon, powernet, this, 1, TRUE)))
            {
                do_sparks(5, TRUE, master);
                return;
            }

            obj_item_stack_cable_coil cable = Dm.@new<obj_item_stack_cable_coil>(drop_location(), 10);
            qdel(this);
            cable.balloon_alert(user, I18n.T("cable terminal dismantled"));
        }
    }

    // tg: code/modules/power/terminal.dm:75
    public override async DmTask<object> wirecutter_act(mob_living user = null, obj_item I = null)
    {
        await base.wirecutter_act(user, I);
        await dismantle(user, I);
        return TRUE;
    }
}
